///  - floatmode must be one of "fixed", "unique", "maxprec", or "maxprec_equal"
///  - legacy must be one of "1.13", "1.21", "1.25", "2.1", or "2.2"
fn set_printoptions(
    precision: Option<u8>,
    threshold: Option<u8>,
    edgeitems: Option<u8>,
    linewidth: Option<u8>,
    suppress: Option<bool>,
    nanstr: Option<String>,
    infstr: Option<String>,
    sign: Option<String>,
    floatmode: Option<String>,
    legacy: Option<String>,
) {
    // Validate numeric options
    if let Some(p) = precision {
        assert(p > 0);
    }
    if let Some(t) = threshold {
        assert(t > 0);
    }
    if let Some(e) = edgeitems {
        assert(e > 0);
    }
    if let Some(w) = linewidth {
        assert(w > 0);
    }

    // suppress: no additional invariants needed

    // Validate nan string
    if let Some(ref s) = nanstr {
        assert(s.len() > 0);
    }
    // Validate infinity string
    if let Some(ref s) = infstr {
        assert(s.len() > 0);
    }

    // Validate sign string
    if let Some(ref s) = sign {
        // must be exactly one character
        assert(s.len() == 1);
        // extract that character
        let c = s.as_str().chars().next().unwrap();
        assert(c == '+' || c == '-' || c == ' ');
    }

    // Validate floatmode
    if let Some(ref m) = floatmode {
        assert(
            m == "fixed"
            || m == "unique"
            || m == "maxprec"
            || m == "maxprec_equal"
        );
    }

    // Validate legacy mode
    if let Some(ref m) = legacy {
        assert(
            m == "1.13"
            || m == "1.21"
            || m == "1.25"
            || m == "2.1"
            || m == "2.2"
        );
    }

    // All provided options have been validated. Ready to apply settings.
}

